	for _, i := range []int{2, 3} {
		transA2.Disconnect(addrs[i])
		trans[i].Disconnect("A")
	}
	fut := raftA.Apply([]byte("two-of-four-write"), 2*time.Second)
	writeErr := fut.Error()
